SELECT no_plan();
CREATE TEMP TABLE geometry_fixture(manifest JSONB,scan TEXT,generation TEXT,digest TEXT);
INSERT INTO geometry_fixture VALUES ('{"schema_version": 9, "items": [{"kind": "image", "source": {"media_id": "00000000-0000-4000-8000-000000000030", "content_type": "image/heif", "byte_count": 33554432, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "prepared": {"media_id": "00000000-0000-4000-8000-000000000031", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "coordinate_basis": "prepared_image_top_left_v1", "focus_region": {"x": 0.1, "y": 0.2, "width": 0.3, "height": 0.4, "source": "user_selection"}, "preparation": {"schema_version": 1, "coordinate_basis": "upright_source_top_left_v1", "format": "nativeSelectedStillImageV2", "crop_display_size": 390, "quarter_turns": 1, "scale": 1.5, "offset_x": -30, "offset_y": 25, "camera_vertical_center": null, "source_selection": {"x": 0.2, "y": 0.3, "width": 0.1, "height": 0.2, "source": "user_selection"}}}, {"kind": "description", "text": "  Synthetic 🦋 context.  "}, {"kind": "video", "source": {"media_id": "00000000-0000-4000-8000-000000000032", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "playback": {"media_id": "00000000-0000-4000-8000-000000000033", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "frames": [{"media_id": "00000000-0000-4000-8000-000000000034", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, {"media_id": "00000000-0000-4000-8000-000000000035", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}], "audio": {"source": {"media_id": "00000000-0000-4000-8000-000000000036", "content_type": "audio/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa