SELECT is(internal.initial_evidence_contract(manifest,scan,generation)->>'evidence_digest',digest,'geometry shared fixture typed digest') FROM geometry_fixture;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',jsonb_set(manifest,'{schema_version}','8'),scan,generation),'22023','invalid_analysis_history','geometry cannot enter historical V8') FROM geometry_fixture;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',manifest #- '{items,0,preparation}',scan,generation),'22023','invalid_analysis_history','V9 requires explicit geometry') FROM geometry_fixture;
SELECT ok(NOT has_function_privilege(role,'internal.initial_photo_preparation_fields(jsonb)','EXECUTE'),role||' has no direct geometry authority') FROM (VALUES('anon'),('authenticated'),('service_role')) r(role);
SELECT is(provolatile::TEXT,'i','geometry fingerprint is immutable') FROM pg_proc WHERE oid='internal.initial_photo_preparation_fields(jsonb)'::regprocedure;
CREATE TEMP TABLE full_selection AS
SELECT (manifest #> '{items,0,preparation}') || '{"crop_display_size":null,"quarter_turns":0,"scale":1,"offset_x":0,"offset_y":0}'::JSONB AS recipe FROM geometry_fixture;
SELECT lives_ok(pg_catalog.format('SELECT internal.initial_photo_preparation_fields(%L::jsonb)',recipe),'full-aspect selection is accepted') FROM full_selection;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_photo_preparation_fields(%L::jsonb)',recipe||delta),'22023','invalid_analysis_history','full-aspect selection rejects nonidentity or missing selection') FROM full_selection CROSS JOIN (VALUES
 ('{"quarter_turns":1}'::JSONB),('{"scale":1.1}'::JSONB),('{"offset_x":1}'::JSONB),('{"offset_y":1}'::JSONB),('{"camera_vertical_center":0.5}'::JSONB),('{"source_selection":null}'::JSONB)) invalid(delta);
SELECT * FROM finish();
ROLLBACK;
